using System.Collections;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ExpelEffect", menuName = "Data/Battle/Effects/Sentinels/Expel Effect")]
public class ExpelEffect : Effect
{
	[Header("Description")]
	[SerializeField]
	private OmenLogicActionFace omenLogicActionFace;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(base.localizationManager.GetWheneverYouShuffleYourDicePool(), omenLogicActionFace.ActionFace.BattleAction.GetActionDescription(amount).LowercaseFirst());
	}

	public override int ActivateEffect(int effectAmount, GameObject effectOwner)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(ShuffleBombCoroutine(effectAmount, effectOwner));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
		return effectAmount;
	}

	private IEnumerator ShuffleBombCoroutine(int effectAmount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
			yield return new WaitForSeconds(0.4f);
			omenLogicActionFace.ActivateOmen(effectAmount);
			yield return new WaitForSeconds(0.3f);
		}
	}
}
